using System.Diagnostics.Metrics;
using System.Text.Json;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Caching.Memory;
namespace Services.Catalog.Services;
public sealed class CacheMetrics(IMeterFactory meters) { private readonly Counter<long> _hits = meters.Create("Catalog.Cache").CreateCounter<long>("cache.hits"); private readonly Counter<long> _misses = meters.Create("Catalog.Cache").CreateCounter<long>("cache.misses"); public void Hit(string level) => _hits.Add(1, new KeyValuePair<string, object?>("cache.level", level)); public void Miss(string level) => _misses.Add(1, new KeyValuePair<string, object?>("cache.level", level)); }
public sealed class TwoLevelCache(IMemoryCache memory, IDistributedCache redis, CacheMetrics metrics, ILogger<TwoLevelCache> log)
{
 public async Task<T?> GetOrCreateAsync<T>(string key, Func<Task<T?>> factory, CancellationToken ct) { if (memory.TryGetValue(key, out T? l1)) { metrics.Hit("L1"); log.LogInformation("Cache hit {Key} {Level}", key, "L1"); return l1; } metrics.Miss("L1"); try { var bytes = await redis.GetAsync(key, ct); if (bytes is not null) { var l2 = JsonSerializer.Deserialize<T>(bytes); memory.Set(key,l2,new MemoryCacheEntryOptions {Size=1,SlidingExpiration=TimeSpan.FromMinutes(1)}); metrics.Hit("L2"); log.LogInformation("Cache hit {Key} {Level}",key,"L2"); return l2; } metrics.Miss("L2"); } catch (Exception ex) { log.LogWarning(ex,"Redis unavailable for {Key}; falling back to source",key); } var value=await factory(); if(value is null)return value; var bytesOut=JsonSerializer.SerializeToUtf8Bytes(value); try { await redis.SetAsync(key,bytesOut,new DistributedCacheEntryOptions{AbsoluteExpirationRelativeToNow=TimeSpan.FromMinutes(10)},ct); }catch(Exception ex){log.LogWarning(ex,"Redis write failed {Key}",key);} memory.Set(key,value,new MemoryCacheEntryOptions{Size=1,SlidingExpiration=TimeSpan.FromMinutes(1)}); log.LogInformation("Cache miss {Key}; source loaded",key); return value; }
 public async Task InvalidateAsync(string key,CancellationToken ct){memory.Remove(key);try{await redis.RemoveAsync(key,ct);}catch(Exception ex){log.LogWarning(ex,"Redis invalidation failed {Key}",key);}log.LogInformation("Cache invalidated {Key}, reason {Reason}",key,"ProductUpdated");}
}
